function outro_sec_screenwriter_1(co)
hss.evt(co,"You're catching up on some reading in the library when {CONNECTED_CHARACTER_NAME} walks up to your table holding a laptop.", "")
hss.dlg(co,"{CONNECTED_CHARACTER}","Hey, {YOU}... are you busy right now? I've been working on this screenplay and, well, I could really use your help.")
hss.dlgA(co,hss.U,"It so happens that helping friends is my specialty! Let me guess, you're struggling with writer's block and need some inspiration? I know just the place to--",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","Um, no, actually. I already wrote the whole thing.",4)
hss.dlgA(co,hss.U,"Oh! Okay, then what do you need my help with?",4)
hss.dlgA(co,"{CONNECTED_CHARACTER}","Well, I learned that one of my friends from high school works as an executive assistant at ~Crown Studios,~ and she agreed to read my screenplay!",1)
hss.dlg(co,"{CONNECTED_CHARACTER}","I've dreamed of seeing my work on the big screen my whole life. This is the first script I've ever finished, and I poured my heart and soul into it. Basically, I ~super~ don't wanna screw this up.")
hss.dlg(co,"{CONNECTED_CHARACTER}","You've got way more real-world experience than I do. You know how to work with Hollywood big shots, how to make deals and get noticed. If anyone can help me out, it's you.")
hss.dlgA(co,hss.U,"Well then, let's see what you've got!",1)
hss.showQuestComplete(co)
hss.evt(co,"You read {CONNECTED_CHARACTER_NAME}'s screenplay, ~The Wilds,~ a bare-bones survival thriller where two friends crash their plane in the mountains and have to fight their way back to civilization.", "")
hss.evt(co,"You blaze through page after page, and it seems like barely a moment has passed before you reach the end. You slowly put the script down.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Uh, you look shocked. Is this like 'Wow, that was amazing' shocked or 'That's the worst thing I've ever read' shocked?",2)
hss.dlgA(co,hss.U,"This... is seriously your first screenplay? You've got to be kidding me. It's ~fantastic!~",4)
hss.dlg(co,"{CONNECTED_CHARACTER}","Oh thank goodness. You think it's good enough to send in? I mean, this is probably the best thing I've ever written... but that doesn't mean it'll sell.")
hss.dlg(co,hss.U,"Realistically? You never know with Hollywood. It's a spec script, and it's got a few rough edges... but in my opinion, a producer would have to be crazy not to consider it.")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Really? You think it'll stand out?",1)
hss.dlg(co,hss.U,"Absolutely. But there ~is~ something you could do to help it stand out even more... we could shoot a sizzle reel!")
hss.dlgA(co,"{CONNECTED_CHARACTER}","A sizzle what?",4)
hss.dlg(co,hss.U,"Sometimes, a writer will shoot a scene or two from their script on their own, like a mini-movie! It really helps producers literally see their work translated to the screen.")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Ooh, that's a great idea! We'd need some actors who could really sell the emotional intensity of the story.",4)
hss.dlg(co,hss.U,"I know just who to cast...")
end
function intro_sec_screenwriter_2(co)
if (hss.getCharacterReferenceNameByProperty("QUEST_CHAR_1") == "YOU") then
hss.evt(co,"That evening, you meet {QUEST_CHAR_2_NAME} in a wooded area of Griffith Park to shoot a scene from {CONNECTED_CHARACTER_NAME}'s screenplay.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Wow... I can't believe {YOU} is going to do a scene from my screenplay!",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","And {QUEST_CHAR_2_NAME} too! If I'm dreaming, nobody pinch me.",4)
hss.dlgA(co,hss.U,"Noted. And thanks for coming out, {QUEST_CHAR_2_NAME}! I can't think of anyone more perfect for this role.",1)
else
hss.evt(co,"That evening, you meet {QUEST_CHAR_1_NAME} and {QUEST_CHAR_2_NAME} in a wooded area of Griffith Park to shoot a scene from {CONNECTED_CHARACTER_NAME}'s screenplay.", "")
hss.dlg(co,hss.U,"Thanks for coming out, you two! I can't think of anyone more perfect for these roles.")
end
hss.dlgA(co,hss.Q2,"Of course! I'm completely in love with this character. So raw, so determined!",1)
hss.dlg(co,"{CONNECTED_CHARACTER}","This scene is a real emotional low point for both characters.")
hss.dlg(co,"{CONNECTED_CHARACTER}","It's getting dark, and a pack of wolves is on your heels. {QUEST_CHAR_2_NAME}, you've got a really bad fever, so you're not fully aware of what's going on. But you know things are ~bad.~")
hss.dlgA(co,hss.Q2,"Wavering in and out of lucidity while fleeing for my life? This is the kind of acting challenge I live for!",1)
hss.dlg(co,"{CONNECTED_CHARACTER}","{QUEST_CHAR_1_NAME}, you're dealing with the decision to keep caring for {QUEST_CHAR_2_NAME}, even though it means drastically decreasing your own chances at survival.")
hss.dlg(co,hss.Q1,"I do love a good moral dilemma. I can't wait to really dig into these conflicting emotions!")
hss.dlgA(co,"{CONNECTED_CHARACTER}","And I can't wait to see my work on film! You guys ready to get started?",1)
hss.dlgA(co,hss.U,"Definitely. Let's do it!",1)
end
function outro_sec_screenwriter_2(co)
if (hss.getCharacterReferenceNameByProperty("QUEST_CHAR_1") == "YOU") then
hss.evt(co,"The cameras start rolling! You stumble through the trees, supporting a delirious {QUEST_CHAR_2_NAME}.", "")
hss.dlgA(co,hss.Q1,"Come on! Those wolves are right behind us... we've gotta keep moving!",3)
hss.dlgA(co,hss.Q2,"I... I can't... so tired...",2)
hss.evt(co,"{QUEST_CHAR_2_NAME} stumbles, and you both fall to the ground.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","This is so cool... they're really becoming my characters!",1)
hss.evt(co,"The camera pushes in on the two of you as {QUEST_CHAR_2_NAME} looks around in confusion.", "")
hss.dlgA(co,hss.Q2,"The plane... what happened to the plane? Wait... I remember... we crashed!",4)
hss.dlgA(co,hss.Q2,"Listen, you have to leave me! ~One~ of us needs to make it out of here alive--",2)
hss.dlgA(co,hss.Q1,"No. I promised your fiance I'd have you back in time for the wedding, and I'm keeping that promise! Now ~get up!~",3)
hss.evt(co,"You hoist {QUEST_CHAR_2_NAME} over one shoulder and trudge on, wolves howling in the background.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Cut! That was awesome!",1)
else
hss.evt(co,"The cameras start rolling! At your signal, {QUEST_CHAR_1_NAME} stumbles through the trees, supporting a delirious {QUEST_CHAR_2_NAME}.", "")
hss.dlgA(co,hss.Q1,"Come on! Those wolves are right behind us... we've gotta keep moving!",3)
hss.dlgA(co,hss.Q2,"I... I can't... so tired...",2)
hss.evt(co,"{QUEST_CHAR_2_NAME} stumbles, and they both fall to the ground.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","This is so cool... they're really becoming my characters!",1)
hss.dlgA(co,hss.U,"Isn't that a great feeling? Now, let's get in close for the big emotional moment...",1)
hss.evt(co,"You dolly towards the two actors as {QUEST_CHAR_2_NAME} looks around in confusion.", "")
hss.dlgA(co,hss.Q2,"The plane... what happened to the plane? Wait... I remember... we crashed!",4)
hss.dlgA(co,hss.Q2,"Listen, you have to leave me! ~One~ of us needs to make it out of here alive--",2)
hss.dlgA(co,hss.Q1,"No. I promised your fiance I'd have you back in time for the wedding, and I'm keeping that promise! Now ~get up!~",3)
hss.evt(co,"{QUEST_CHAR_1_NAME} hoists {QUEST_CHAR_2_NAME} over one shoulder and trudges on, wolves howling in the background.", "")
hss.dlgA(co,hss.U,"Cut! Great work, you two!",1)
end
hss.evt(co,"Later, you review the final cut in the editing studio.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","I can't believe it. This is just how it looked in my head, only better!",4)
hss.dlgA(co,hss.U,"That's what I like to hear. Let's get it to your friend at Crown Studios!",1)
hss.showQuestComplete(co)
hss.evt(co,"The next day, you stop by the Screenwriter Dorm to check in with {CONNECTED_CHARACTER_NAME}.", "")
hss.dlg(co,hss.U,"Hey! Any news from your friend at Crown Studios?")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Yeah, actually. I got an email from her a few minutes ago... and I'm kinda scared to open it.",4)
hss.dlg(co,hss.U,"Do you want me to do it?")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Yes please.",2)
hss.evt(co,"{CONNECTED_CHARACTER_NAME} slides over the laptop, and you open the message from Crown Studios.", "")
hss.dlgA(co,hss.U,"Oh my god...",4)
hss.dlgA(co,"{CONNECTED_CHARACTER}","What? What does it say? Did she hate it?",2)
hss.dlgA(co,hss.U,"She ~loved~ it... and so did her boss!",1)
end
function intro_sec_screenwriter_3(co)
hss.evt(co,"{CONNECTED_CHARACTER_NAME} grabs the laptop back and reads the email from Crown Studios.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","No way... they want me to pitch my screenplay to the full board of executives! But...",4)
hss.dlgA(co,"{CONNECTED_CHARACTER}","Oh no... how can they ask me to do that?!",2)
hss.dlgA(co,hss.U,"Uh oh. What's wrong?",2)
hss.dlgA(co,"{CONNECTED_CHARACTER}","My friend's boss thought that the relationship between the main characters was too bland. They want to rewrite it as a love story.",2)
hss.dlg(co,hss.U,"Oh, that's not so bad. I thought they asked you to pitch it while wearing a chicken suit or something.")
hss.dlgA(co,"{CONNECTED_CHARACTER}","But... this screenplay is my baby! It's so amazing that they're interested, but I don't know if I want to change my work just to suit their preferences.",2)
hss.dlgA(co,hss.U,"{CONNECTED_CHARACTER_NAME}... I know it's hard, but I think you should make this change, because...",2)
local choice = hss.showTextMenu(co, "Why make the change?", "It's a better story.|It's good marketing.");
if (choice == 0) then
hss.dlg(co,hss.U,"Think about it. One of your characters is getting married, right? Imagine how much tension it would add to the plot to inject a little unrequited love!")
hss.dlg(co,"{CONNECTED_CHARACTER}","Hmm... that ~would~ make the forest scene a lot more powerful...")
else
hss.dlg(co,hss.U,"As is, this would be one seriously dark movie. Crown Studios wouldn't want to limit its audience, and if you're going for four-quadrant appeal, injecting a little romantic tension would go a long way.")
hss.dlg(co,"{CONNECTED_CHARACTER}","Yeah... I suppose there's a reason why most movies have a love story...")
end
hss.dlg(co,hss.U,"Exactly. I know you're really attached to this screenplay, but if you want to see it on the big screen, you've got to accept that it probably won't be exactly how you pictured it.")
hss.dlg(co,hss.U,"But... that's the price we pay to get our work out in the world.")
hss.dlg(co,"{CONNECTED_CHARACTER}","Well... sounds like I've got a lot of work to do if I'm gonna be ready for that pitch meeting on Friday.")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Uh, any chance you'd be willing to come with me? I've never done one of these before. I could use some moral support.",2)
hss.dlgA(co,hss.U,"Of course I'll come! You write like the wind. I'll meet you at the studio on Friday...",1)
end
function outro_sec_screenwriter_3(co)
hss.evt(co,"Early Friday morning, you and {CONNECTED_CHARACTER_NAME} pull up outside the Crown Studios building.", "")
hss.dlg(co,hss.U,"So how'd the rewrites go? You happy with the new draft?")
hss.dlgA(co,"{CONNECTED_CHARACTER}","I don't know... I've never had to incorporate someone else's ideas into my work before. I'm worried I might have ruined the whole thing.",2)
hss.dlg(co,hss.U,"With your writing skills? I seriously doubt you ruined anything. Come on, the meeting is starting soon...")
hss.evt(co,"The receptionist directs you to a conference room on the thirtieth floor. Inside, you sit down at a table crowded with middle-aged executives in expensive suits.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Um... hi! I mean, thanks for having me. I sent over the new script last night, did you get a chance to--",4)
hss.evt(co,"One of the execs interjects, telling {CONNECTED_CHARACTER_NAME} how much he loved the new draft!", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Wait... seriously?",4)
hss.evt(co,"More of the executives chime in, gushing over the script and suggesting ways to make it even better.", "")
hss.dlgA(co,hss.U,"...a summer blockbuster? Well, ~The Wilds~ was written as more of a low-budget indie movie... but sure, I think it has the potential!",4)
hss.evt(co,"Several executives toss around the names of A-list actors who could play the lead character. They pepper {CONNECTED_CHARACTER_NAME} with requests and questions.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","Um, I actually ~didn't~ have a particular actor in mind. {YOU}, do you have any ideas?",4)
hss.dlgA(co,hss.U,"Oh yeah. You know who'd be perfect for this role?",1)
local choice = hss.showTextMenu(co, "Who should play the lead?", "Angelina Jolie!|Chris Hemsworth!|Steve Buscemi!|Me!");
if (choice == 0) then
hss.dlgA(co,hss.U,"Moviegoers are ~clamoring~ for more awesome female leads. Angelina can do drama, she can do romance, and she can ~definitely~ do action!",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","You're right! With a few tweaks, this role would be perfect for her!",1)
elseif (choice == 1) then
hss.dlgA(co,hss.U,"Hemsworth is ~hot~ right now! He's got star power, ~and~ he's proven that he can play an action hero with real emotional depth.",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","You're right! With a few tweaks, this role would be perfect for him!",1)
elseif (choice == 2) then
hss.dlgA(co,"{CONNECTED_CHARACTER}","That's an... unconventional choice.",4)
hss.dlg(co,hss.U,"Hey, if you want your movie to stand out? You've gotta think outside the box.")
hss.dlgA(co,hss.U,"Besides, have you ~seen~ him in Boardwalk Empire? Go home and watch it, you'll see him in a whole new light.",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","You know, now that I'm thinking about it... he could be perfect!",1)
else
hss.dlgA(co,"{CONNECTED_CHARACTER}","~You~ want to star in my movie?",4)
hss.dlgA(co,hss.U,"You deserve the best, and I'm the best I know.",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","I'd be honored. But, um, maybe let's keep brainstorming?",1)
end
hss.evt(co,"The ideas continue to fly around the room, and {CONNECTED_CHARACTER_NAME} takes notes on a laptop, typing furiously.", "")
hss.dlgA(co,"{CONNECTED_CHARACTER}","No, you're totally right. There really ~isn't~ a reason it couldn't take place on Mars! I'll just change the plane to a spaceship, and the wolves to Martian wolves!",4)
hss.dlg(co,hss.U,"I guess Mars colonization ~is~ pretty in right now...")
hss.showQuestComplete(co)
hss.evt(co,"On the way back to the car, you turn to {CONNECTED_CHARACTER_NAME}, who is poring over all the notes from the meeting.", "")
hss.dlgA(co,hss.U,"So, that went ~amazingly~ well. Your very first screenplay might end up as Crown Studios' summer tentpole!",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","Right?! Did you ~hear~ all the actors they want to approach for the lead roles? Can you ~imagine~ an A-list star reading ~my~ words?!",1)
hss.dlgA(co,hss.U,"I can now! Seems like those execs were totally enchanted with your screenplay!",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","I ~know!~ I was on fire in there! I'm so close to realizing my lifelong dream, I can taste it! And it tastes ~good.~",1)
hss.dlgA(co,"{CONNECTED_CHARACTER}","I can't wait to get started on those re-writes, and we should ~definitely~ re-shoot the sizzle reel to really seal the deal!",1)
hss.dlg(co,"{CONNECTED_CHARACTER}","But this time it's gotta be ~bigger~ and ~sexier!~ We'll need to cast some new actors...")
hss.dlgA(co,"{CONNECTED_CHARACTER}","You know what? They don't actually need any acting experience. They just need to be hot. Like, off-the-charts hot! You know anyone who fits the bill?",1)
end
function intro_sec_screenwriter_4(co)
hss.evt(co,"Back in one of the campus studios, everyone reads through the new script as the crew sets up the new set in front of a towering green screen.", "")
hss.dlg(co,hss.Q1,"Hey {CONNECTED_CHARACTER_NAME}, how do I pronounce this word?")
hss.dlg(co,"{CONNECTED_CHARACTER}","'Drak-uh-gar', it's a type of insectoid wolf indigenous to the Martian outback.")
hss.dlg(co,hss.Q2,"Okay, and my character is suffering from 'red lung'? What's that?")
hss.dlg(co,hss.U,"According to the script notes... it's a 'pneumonia-like disease that includes fever and coughing'.")
hss.dlgA(co,hss.U,"Wow! Uh... this script is pretty different than the last draft.",4)
hss.dlg(co,"{CONNECTED_CHARACTER}","Yeah, I had to make a lot of changes to incorporate all the Crown execs' suggestions. It's like you said, my work isn't gonna look exactly the same as I imagined it.")
hss.dlgA(co,"{CONNECTED_CHARACTER}","But hey, those studio execs know what they're doing way better than I do. As long as I get to see my baby on the big screen? I'm a happy camper.",1)
hss.dlg(co,hss.U,"All right then, let's shoot this scene! Everyone on your marks...")
end
